import {quizTrophies,trophyProgress} from './quiz-trophies-core.mjs';
import {quizTime} from './quiz-records-core.mjs';
const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
export function mountQuizTrophies(container,{snapshot,play}){
 container.className='quiz-trophy-collection';container.innerHTML=`<div data-trophy-shelf><div class="quiz-collection-heading"><div><span class="quiz-collection-eyebrow">First edition</span><h3>Your collection</h3></div><span data-trophy-count></span></div><p class="quiz-collection-caption">Four original 3D keepsakes to earn through your quizzes.</p><div class="quiz-trophy-grid"></div><p class="quiz-collection-note">Unlock each with 100% in all three full first-level quiz modes, without hints or revealed answers. Existing qualifying records count too.</p></div><section data-trophy-detail hidden><button class="quiz-country-back" type="button" data-trophy-back><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg>All collectibles</button><div class="quiz-trophy-inspect"><div class="quiz-trophy-stage"><img data-trophy-poster alt=""><div data-trophy-canvas></div><span class="quiz-trophy-edition">Atlas collection · 01</span></div><div class="quiz-trophy-info"><span data-trophy-country class="quiz-collection-eyebrow"></span><h3 data-trophy-title tabindex="-1"></h3><span data-trophy-material class="quiz-trophy-material"></span><p data-trophy-description></p><div class="quiz-trophy-status" data-trophy-status></div><h4 data-trophy-goal></h4><p class="quiz-trophy-requirement">Get 100% in all three modes, each in a full first-level round without hints or revealed answers.</p><div class="quiz-trophy-progress"><span data-trophy-progress></span><div role="progressbar" aria-label="Quiz modes completed" aria-valuemin="0" aria-valuemax="100"><span></span></div></div><ul class="quiz-trophy-mode-list" data-trophy-modes></ul><button class="account-primary" type="button" data-trophy-play>Play country quiz</button><a class="quiz-trophy-download" data-trophy-download download hidden>Download your 3D model</a></div></div><div class="quiz-trophy-viewer-controls"><p data-trophy-viewer-note role="status">Drag to rotate · arrow keys work too</p><button type="button" data-trophy-reset>Reset view</button></div></section>`;
 const $=s=>container.querySelector(s),definitions=AtlasCountries.countries,cards=new Map();let selected=null,active=false,viewer=null,version=0,loading=false,earnedCount=0,shelfScroll=0;
 function dispose(){version++;viewer?.dispose();viewer=null;loading=false;$('[data-trophy-canvas]').replaceChildren();$('[data-trophy-poster]').hidden=false;}
 function flags(country){const img=make('img');img.src=definitions[country].quiz.flags[0];img.alt='';img.width=24;img.height=16;return img;}
 for(const trophy of quizTrophies){const card=make('button',undefined,'quiz-trophy-card');card.type='button';card.dataset.trophyCard=trophy.country;card.style.setProperty('--trophy-tint',trophy.tint);const art=make('span',undefined,'quiz-trophy-art'),poster=make('img');poster.src=trophy.poster;poster.alt='';poster.loading='lazy';poster.decoding='async';art.append(poster);const badge=make('span',undefined,'quiz-trophy-badge'),body=make('span',undefined,'quiz-trophy-card-body'),country=make('span',undefined,'quiz-trophy-card-country');country.append(flags(trophy.country),make('span',definitions[trophy.country].en));body.append(country,make('strong',trophy.name),make('span',trophy.goal,'quiz-trophy-card-goal'),badge);card.append(art,body);card.onclick=()=>open(trophy.country);$('.quiz-trophy-grid').append(card);cards.set(trophy.country,{card,badge});}
 function refresh(){
  const data=snapshot();earnedCount=0;for(const trophy of quizTrophies){const state=trophyProgress(trophy,data),{card,badge}=cards.get(trophy.country);if(state.earned)earnedCount++;card.dataset.earned=String(state.earned);card.setAttribute('aria-label',trophy.name+' · '+definitions[trophy.country].en+' · '+(state.earned?'Collected':'Locked'));badge.textContent=state.earned?'Collected':state.completedModes+' / 3 modes complete';}
  $('[data-trophy-count]').textContent=earnedCount+' / '+quizTrophies.length+' collected';
  if(selected){const state=trophyProgress(selected,data);$('[data-trophy-status]').textContent=state.earned?'Collected':'Not yet collected';$('[data-trophy-status]').dataset.earned=String(state.earned);$('[data-trophy-goal]').textContent=selected.goal;$('[data-trophy-progress]').textContent=state.completedModes+' / 3 modes complete';const modeList=$('[data-trophy-modes]');modeList.replaceChildren();for(const mode of state.modes){const row=make('li');row.dataset.trophyMode=mode.id;row.dataset.complete=String(mode.earned);const label=make('span',mode.label),result=make('span',mode.earned?'100% · '+quizTime(mode.fastestMs):mode.correct===mode.total?'Finish without hints':mode.correct+' / '+mode.total);row.append(label,result);modeList.append(row);}const progress=$('[role=progressbar]');progress.setAttribute('aria-valuenow',String(state.percent));progress.firstElementChild.style.width=state.percent+'%';$('[data-trophy-download]').hidden=!state.earned;$('[data-trophy-download]').href=selected.file;$('[data-trophy-play]').textContent=state.earned?'Play again':'Play: '+state.modes.find(m=>!m.earned).label;}
 }
 async function renderModel(){
  if(!active||!selected||viewer||loading||!container.closest('dialog')?.open||!$('[data-trophy-detail]').getClientRects().length)return;loading=true;const token=version,trophy=selected,canvas=make('canvas');canvas.tabIndex=0;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Interactive 3D '+trophy.name+'. Drag or use arrow keys to rotate.');$('[data-trophy-canvas]').replaceChildren(canvas);$('[data-trophy-viewer-note]').textContent='Drag to rotate · arrow keys work too';$('[data-trophy-reset]').hidden=true;
  try{const {createTrophyViewer}=await import('./trophy-viewer.mjs');if(token!==version)return;const created=await createTrophyViewer(canvas,trophy.file,{onError(){dispose();$('[data-trophy-viewer-note]').textContent='3D preview is unavailable. The model thumbnail is shown.';}});if(token!==version){created.dispose();return;}viewer=created;$('[data-trophy-poster]').hidden=true;$('[data-trophy-reset]').hidden=false;canvas.dataset.ready='true';}
  catch{if(token===version){canvas.remove();$('[data-trophy-viewer-note]').textContent='3D preview is unavailable. The model thumbnail is shown.';}}
  finally{if(token===version)loading=false;}
 }
 function open(country){shelfScroll=container.closest('dialog')?.scrollTop||0;const trophy=quizTrophies.find(t=>t.country===country);if(!trophy)return;dispose();selected=trophy;container.parentElement.dataset.trophyOpen='true';$('[data-trophy-shelf]').hidden=true;$('[data-trophy-detail]').hidden=false;$('[data-trophy-country]').textContent=definitions[country].en;$('[data-trophy-title]').textContent=trophy.name;$('[data-trophy-material]').textContent=trophy.material;$('[data-trophy-description]').textContent=trophy.description;$('.quiz-trophy-stage').style.setProperty('--trophy-tint',trophy.tint);$('[data-trophy-poster]').src=trophy.poster;refresh();container.closest('dialog')?.scrollTo({top:0,behavior:'instant'});$('[data-trophy-title]').focus({preventScroll:true});void renderModel();}
 $('[data-trophy-back]').onclick=()=>{const previous=selected?.country;dispose();selected=null;container.parentElement.dataset.trophyOpen='false';$('[data-trophy-shelf]').hidden=false;$('[data-trophy-detail]').hidden=true;if(container.closest('dialog'))container.closest('dialog').scrollTop=shelfScroll;cards.get(previous)?.card.focus({preventScroll:true});};$('[data-trophy-reset]').onclick=()=>viewer?.reset();$('[data-trophy-play]').onclick=()=>play({country:selected.country,level:1,mode:trophyProgress(selected,snapshot()).modes.find(m=>!m.earned)?.id||'name',scope:''});
 container.closest('dialog')?.addEventListener('close',dispose);container.closest('dialog')?.addEventListener('click',event=>{const tab=event.target.closest('[data-account-section]');if(tab?.dataset.accountSection==='profile')dispose();else if(tab?.dataset.accountSection==='quizzes')requestAnimationFrame(()=>void renderModel());});
 return{refresh(){refresh();void renderModel();},setActive(value){container.parentElement.dataset.trophyOpen=String(value&&!!selected);if(active===value){if(value)void renderModel();return;}active=value;if(!value)dispose();else void renderModel();},reset(){dispose();selected=null;$('[data-trophy-shelf]').hidden=false;$('[data-trophy-detail]').hidden=true;},get count(){return earnedCount;},focus(){(selected?$('[data-trophy-back]'):cards.get(quizTrophies[0].country).card).focus({preventScroll:true});}};
}
